 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "seidel-2d.h"

/* Include the Exo-generated kernel header. */
#include "generated/seidel-2d/seidel-2d.h"


/* Array initialization. */
static
void init_array (int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline Seidel-2D stencil kernel. We keep the mathematical definition
# simple and apply loop transformations below via Exo's scheduling API.
@proc
def kernel_seidel_2d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # We update the interior points A[1:n-1, 1:n-1] in place.
    assert n > 2

    for t in seq(0, tsteps):
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                A[i, j] = (
                    A[i - 1, j - 1] + A[i - 1, j] + A[i - 1, j + 1]
                    + A[i,     j - 1] + A[i,     j] + A[i,     j + 1]
                    + A[i + 1, j - 1] + A[i + 1, j] + A[i + 1, j + 1]
                ) / 9.0

# --------------------------------------------------------------------
# Scheduling / optimization
#
# Goal:
#   - Improve instruction-level parallelism and make it easier for the
#     backend C compiler to vectorize along the inner j-dimension.
#   - Preserve the exact Gauss–Seidel update order and in-place semantics.
#
# Strategy:
#   1. Shift the inner j-loop to start at 0 instead of 1: this gives a
#      canonical 0-based loop which is more convenient for strip-mining.
#   2. Strip-mine (divide) the j-loop by a constant factor J_BLOCK.
#   3. Fully unroll the small inner strip j_inner, exposing a sequence
#      of straight-line stencil updates.
#   4. Simplify algebraic index expressions introduced by the transform.
#
# All transformations are performed with Exo primitives that are
# equivalence-preserving; they do not change the executed iteration
# order of (t, i, j) and therefore preserve the original semantics.
# --------------------------------------------------------------------

p = kernel_seidel_2d

# 1) Shift the inner j-loop to start at 0 instead of 1. This makes the
#    loop bounds canonical (0 .. n-3) while automatically adjusting all
#    index expressions inside the loop body.
j_loop = p.find_loop("j")
p = shift_loop(p, j_loop, "0")

# 2) Strip-mine the (now 0-based) j-loop by a small constant factor.
#    This creates a fixed-size inner loop that we can safely unroll.
J_BLOCK = 4
j_loop = p.find_loop("j")
p = divide_loop(p, j_loop, J_BLOCK, ("j_outer", "j_inner"), tail="guard")

# 3) Unroll the small inner strip j_inner completely. Unrolling preserves
#    the per-iteration order within each strip, which is crucial for the
#    Gauss–Seidel style dependencies along j.
j_inner = p.find_loop("j_inner")
p = unroll_loop(p, j_inner)

# 4) Simplify constant index arithmetic and any dead control introduced
#    by the strip-mining + unrolling.
p = simplify(p)

# Expose the optimized version under the original name so that the C
# driver continues to call `kernel_seidel_2d` without any changes.
kernel_seidel_2d = p
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_seidel_2d(/*ctxt=*/NULL, tsteps, n,
                   (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
